43: func NewDocFromSnapshot(rootId string, snapshot *pb.ChangeSnapshot, opts ...SnapshotOption) (*State, error) {
44: 	if snapshot == nil {
45: 		return nil, fmt.Errorf("nil snapshot")
46: 	}
47: 	if snapshot.Data == nil {
48: 		return nil, fmt.Errorf("nil snapshot data")
49: 	}
50: 
51: 	sOpts := snapshotOptions{}
52: 	for _, opt := range opts {
53: 		opt(&sOpts)
54: 	}
55: 	blocks := make(map[string]simple.Block)
56: 	for _, b := range snapshot.Data.Blocks {
57: 		blocks[b.Id] = simple.New(b)
58: 	}
59: 	fileKeys := make([]pb.ChangeFileKeys, 0, len(snapshot.FileKeys))
60: 	for _, fk := range snapshot.FileKeys {
61: 		fileKeys = append(fileKeys, *fk)
62: 	}
63: 
64: 	// clear nil values
65: 	pbtypes.StructDeleteEmptyFields(snapshot.Data.Details)
66: 
67: 	removedCollectionKeysMap := make(map[string]struct{}, len(snapshot.Data.RemovedCollectionKeys))
68: 	for _, t := range snapshot.Data.RemovedCollectionKeys {
69: 		removedCollectionKeysMap[t] = struct{}{}
70: 	}
71: 
72: 	detailsFromSnapshot := pbtypes.StructCutKeys(snapshot.Data.Details, slice.IntoStrings(bundle.LocalAndDerivedRelationKeys))
73: 	if err := pbtypes.ValidateStruct(detailsFromSnapshot); err != nil {
74: 		log.Errorf("NewDocFromSnapshot details validation error: %v; details normalized", err)
75: 		pbtypes.NormalizeStruct(detailsFromSnapshot)
76: 	}
77: 
78: 	details := domain.NewDetailsFromProto(detailsFromSnapshot)
79: 
80: 	s := &State{
81: 		changeId:                 sOpts.changeId,
82: 		rootId:                   rootId,
83: 		blocks:                   blocks,
84: 		details:                  details,
85: 		relationLinks:            snapshot.Data.RelationLinks,
86: 		objectTypeKeys:           migrateObjectTypeIDsToKeys(snapshot.Data.ObjectTypes),
87: 		fileKeys:                 fileKeys,
88: 		store:                    snapshot.Data.Collections,
89: 		storeKeyRemoved:          removedCollectionKeysMap,
90: 		uniqueKeyInternal:        snapshot.Data.Key,
91: 		originalCreatedTimestamp: snapshot.Data.OriginalCreatedTimestamp,
92: 	}
93: 	s.setFileInfoFromModel(snapshot.Data.FileInfo)
94: 
95: 	if sOpts.internalKey != "" {
96: 		s.uniqueKeyInternal = sOpts.internalKey
97: 	}
98: 
99: 	if s.store != nil {
100: 		for collName, coll := range s.store.Fields {
101: 			if c := coll.GetStructValue(); c != nil {
102: 				for k := range c.GetFields() {
103: 					s.setStoreChangeId(collName+addr.SubObjectCollectionIdSeparator+k, s.changeId)
104: 				}
105: 			}
106: 		}
107: 	}
108: 
109: 	return s, nil
110: }
