204: // Decode every persisted non-root record through the original strict companion,
205: // including records older than CommonSnapshot. Current-state replay alone does
206: // not visit those rows. Native keys and decryption are the same as IterateFrom;
207: // no replacement protobuf, compression, or state codec is used.
208: func validateFixedSchemaStoredContent(ctx context.Context, acl list.AclList, rootID string, changes []*objecttree.Change) error {
209: 	for _, change := range changes {
210: 		if err := ctx.Err(); err != nil {
211: 			return err
212: 		}
213: 		if change.Id == rootID {
214: 			continue
215: 		}
216: 		data := change.Data
217: 		if change.ReadKeyId != "" {
218: 			acl.RLock()
219: 			keys, found := acl.AclState().Keys()[change.ReadKeyId]
220: 			acl.RUnlock()
221: 			if !found || keys.ReadKey == nil {
222: 				return list.ErrNoReadKey
223: 			}
224: 			var err error
225: 			data, err = keys.ReadKey.DecryptReuse(nil, data)
226: 			if err != nil {
227: 				return fmt.Errorf("decrypt original stored content: %w", err)
228: 			}
229: 		}
230: 		decoded, err := sourceimpl.UnmarshalChangeStrict(change, data)
231: 		if err != nil {
232: 			return fmt.Errorf("decode original stored content: %w", err)
233: 		}
234: 		model, ok := decoded.(*pb.Change)
235: 		if !ok || model == nil || change.IsSnapshot != (model.Snapshot != nil) {
236: 			return fmt.Errorf("%w: original snapshot content marker", ErrFixedSchemaStorage)
237: 		}
238: 	}
239: 	return nil
240: }
